<script setup lang="ts">
import { computed, ref } from 'vue'
const dataset=ref('A'),state=ref('ready'),selected=ref(0),encoding=ref('radius')
const labels=['North','East','South','West']
const values=computed(()=>dataset.value==='A'?[25,50,75,100]:dataset.value==='B'?[80,60,40,20]:[0,0,0,0])
const radius=(v:number)=>encoding.value==='radius'?v*.8:Math.sqrt(v/100)*80
const point=(r:number,a:number)=>[160+r*Math.cos((a-90)*Math.PI/180),115+r*Math.sin((a-90)*Math.PI/180)]
function sector(v:number,i:number){const r=radius(v),a=point(r,i*90-32),b=point(r,i*90+32);return `M160,115 L${a[0]},${a[1]} A${r},${r} 0 0 1 ${b[0]},${b[1]} Z`}
function reset(){dataset.value='A';state.value='ready';selected.value=0;encoding.value='radius'}
</script>
<template>
<section class="plusage-demo" aria-label="Local polar chart example"><p>Synthetic directional units. Four equal-angle sectors share a central zero. Radius-linear emphasizes radial length; Area-linear makes sector area proportional to value.</p><div class="plusage-controls"><label>Dataset<select v-model="dataset"><option>A</option><option>B</option><option value="zero">All zero</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option></select></label><label>Encoding<select v-model="encoding"><option value="radius">Radius-linear</option><option value="area">Area-linear</option></select></label><button type="button" @click="reset">Reset example</button></div><template v-if="state==='ready'"><p class="plusage-legend">{{ encoding==='radius'?'Radius = 0.8 × value. Sector area grows with value squared.':'Radius = 80 × √(value / 100). Sector area grows with value.' }}</p><svg :key="dataset+'-'+encoding" viewBox="0 0 320 240" role="img" aria-label="Four directional sectors, equal 64 degree angles with gaps, fixed values zero to one hundred. Exact values and radial lengths are below."><circle v-for="tick in [25,50,75,100]" :key="tick" cx="160" cy="115" :r="radius(tick)" class="plusage-ring"/><template v-for="(v,i) in values" :key="i"><path v-if="v>0" class="plusage-sector" :class="{selected:selected===i}" :d="sector(v,i)" :data-radius="radius(v)" :data-index="i"/><circle v-else class="plusage-zero" cx="160" cy="115" r="2"/></template><text x="160" y="17" text-anchor="middle">North</text><text x="255" y="119">East</text><text x="160" y="223" text-anchor="middle">South</text><text x="65" y="119" text-anchor="end">West</text><text x="221" y="49">100</text><text x="164" y="119">0</text></svg><div role="group" aria-label="Select direction" class="plusage-choices"><button v-for="(label,i) in labels" :key="label" type="button" :aria-pressed="selected===i" @click="selected=i" @focus="selected=i">{{ label }}</button></div><p role="status">{{ labels[selected] }}: {{ values[selected] }} units; radius {{ radius(values[selected]).toFixed(2) }} SVG units.</p><table class="plusage-data"><caption>Exact synthetic values, dataset {{ dataset }}</caption><thead><tr><th scope="col">Direction</th><th scope="col">Value</th><th scope="col">Radius</th></tr></thead><tbody><tr v-for="(label,i) in labels" :key="label"><th scope="row">{{ label }}</th><td>{{ values[i] }}</td><td>{{ radius(values[i]).toFixed(2) }}</td></tr></tbody></table></template><p v-else role="status" class="plusage-state">{{ state==='loading'?'Loading demonstration only; no request is running. Values are withheld.':'No sample directions in this state. Choose Ready to recover.' }}</p></section>
</template>
<style scoped>
.plusage-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.plusage-controls{display:flex;gap:14px;flex-wrap:wrap;align-items:end}.plusage-controls label{display:flex;gap:8px;align-items:center;font-size:13px}.plusage-demo select{appearance:auto;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}.plusage-demo button{padding:6px 9px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.plusage-demo :is(button,select):focus-visible{outline:2px solid var(--vp-c-brand-1);outline-offset:3px}.plusage-legend{display:flex;gap:16px;flex-wrap:wrap;margin-top:18px;font-size:12px}.plusage-demo svg{display:block;width:100%;height:auto;max-height:330px;margin:16px 0;animation:plusage-in .2s ease-out}.plusage-grid{stroke:var(--vp-c-divider);stroke-dasharray:3 4}.plusage-demo svg text{fill:var(--vp-c-text-2);font-size:10px}.plusage-pair{opacity:.65}.plusage-pair.selected{opacity:1}.plusage-pair.selected text{font-weight:700;fill:var(--vp-c-text-1)}.plusage-gap{stroke:var(--vp-c-brand-1);stroke-width:2}.plusage-pair.selected .plusage-gap{stroke-width:4}.plusage-sector{fill:var(--vp-c-brand-1);fill-opacity:.55;stroke:var(--vp-c-brand-1);stroke-width:1}.plusage-sector.selected{fill-opacity:1;stroke:var(--vp-c-text-1);stroke-width:2}.plusage-ring{fill:none;stroke:var(--vp-c-divider);stroke-dasharray:3 3}.plusage-zero{fill:var(--vp-c-text-1)}.plusage-choices{display:flex;gap:6px;flex-wrap:wrap}.plusage-choices button[aria-pressed=true]{background:var(--vp-c-brand-soft);font-weight:700}.plusage-data{display:table!important;width:100%;font-size:12px}.plusage-data caption{text-align:left;padding:8px 0;color:var(--vp-c-text-2)}.plusage-data :is(td,th){padding:6px!important}.plusage-state{padding:16px;background:var(--vp-c-bg-soft);border-radius:10px}@keyframes plusage-in{from{opacity:.4}to{opacity:1}}@media(prefers-reduced-motion:reduce){.plusage-demo svg{animation:none}}
</style>
